package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/benchmark/evidence"
	"github.com/DocumentDrivenDX/fizeau/internal/benchmark/profile"
)

const terminalBenchMatrixMetadataName = "matrix.metadata.json"

func cmdEvidenceImportTerminalBench(args []string) int {
	fs := flagSet("evidence import-terminalbench")
	workDir := fs.String("work-dir", "", "Repository root (default: cwd)")
	matrixDir := fs.String("matrix", "", "TerminalBench matrix output directory")
	outPath := fs.String("out", "", "Output JSONL path")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if strings.TrimSpace(*matrixDir) == "" || strings.TrimSpace(*outPath) == "" {
		fmt.Fprintf(os.Stderr, "Usage: %s evidence import-terminalbench --matrix <dir> --out <records.jsonl>\n", benchCommandName())
		return 2
	}

	wd := resolveWorkDir(*workDir)
	matrixRoot := resolveMatrixPath(wd, *matrixDir)
	outFile := resolveMatrixPath(wd, *outPath)

	matrixOut, err := loadTerminalBenchMatrixOutput(matrixRoot)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: load matrix: %v\n", benchCommandName(), err)
		return 1
	}

	metadata, _ := loadTerminalBenchMatrixMetadata(matrixRoot)
	subsetPath := resolveBenchmarkPath(wd, matrixRoot, matrixOut.SubsetPath)
	subset, err := loadTermbenchSubset(subsetPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: load subset %s: %v\n", benchCommandName(), subsetPath, err)
		return 1
	}

	records := make([]map[string]any, 0, len(matrixOut.Runs))
	if len(matrixOut.Runs) > 0 {
		for _, run := range matrixOut.Runs {
			record, err := buildTerminalBenchRecord(wd, matrixRoot, matrixOut, subset, metadata, run)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: %v\n", benchCommandName(), err)
				return 1
			}
			records = append(records, record)
		}
	} else if len(matrixOut.Cells) > 0 {
		for _, cell := range matrixOut.Cells {
			record, err := buildTerminalBenchAggregateRecord(matrixRoot, matrixOut, subset, metadata, cell)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: %v\n", benchCommandName(), err)
				return 1
			}
			records = append(records, record)
		}
	} else {
		fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: matrix.json contains no runs or cells\n", benchCommandName())
		return 1
	}

	if err := os.MkdirAll(filepath.Dir(outFile), 0o750); err != nil {
		fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: create output dir: %v\n", benchCommandName(), err)
		return 1
	}
	tmp, err := os.CreateTemp(filepath.Dir(outFile), filepath.Base(outFile)+".*.tmp")
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: create temp output: %v\n", benchCommandName(), err)
		return 1
	}
	tmpName := tmp.Name()
	writeErr := writeBenchmarkEvidenceJSONL(tmp, records)
	closeErr := tmp.Close()
	if writeErr == nil {
		writeErr = closeErr
	}
	if writeErr != nil {
		_ = os.Remove(tmpName)
		fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: write output: %v\n", benchCommandName(), writeErr)
		return 1
	}

	validator, err := evidence.NewValidator(wd)
	if err != nil {
		_ = os.Remove(tmpName)
		fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: %v\n", benchCommandName(), err)
		return 1
	}
	if _, err := validator.ValidateFile(tmpName); err != nil {
		_ = os.Remove(tmpName)
		fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: validate output: %v\n", benchCommandName(), err)
		return 1
	}
	if err := os.Rename(tmpName, outFile); err != nil {
		_ = os.Remove(tmpName)
		fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: rename output: %v\n", benchCommandName(), err)
		return 1
	}

	fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: imported %d record(s) to %s\n", benchCommandName(), len(records), outFile)
	return 0
}

func loadTerminalBenchMatrixOutput(matrixRoot string) (*matrixOutput, error) {
	raw, err := os.ReadFile(filepath.Join(matrixRoot, "matrix.json"))
	if err != nil {
		return nil, fmt.Errorf("read matrix.json: %w", err)
	}
	var out matrixOutput
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, fmt.Errorf("parse matrix.json: %w", err)
	}
	return &out, nil
}

func loadTerminalBenchMatrixMetadata(matrixRoot string) (map[string]any, error) {
	path := filepath.Join(matrixRoot, terminalBenchMatrixMetadataName)
	raw, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("read %s: %w", path, err)
	}
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil, fmt.Errorf("parse %s: %w", path, err)
	}
	return doc, nil
}

func buildTerminalBenchRecord(workDir, matrixRoot string, matrix *matrixOutput, subset *termbenchSubset, metadata map[string]any, run matrixRunReport) (map[string]any, error) {
	profilePath := resolveBenchmarkPath(workDir, matrixRoot, run.ProfilePath)
	prof, err := profile.Load(profilePath)
	if err != nil {
		return nil, fmt.Errorf("load profile %s: %w", profilePath, err)
	}

	record := terminalBenchBaseRecord(matrixRoot, matrix, subset, metadata, run, prof)
	record["source"] = terminalBenchSourceRecord(matrixRoot, "matrix.json", run.OutputDir)
	record["score"] = terminalBenchScoreRecord(run, 0)
	record["final_status"] = run.FinalStatus
	if invalidClass := classifyMatrixInvalid(run); invalidClass != "" {
		record["invalid_class"] = invalidClass
		record["scope"].(map[string]any)["denominator_rule"] = "exclude_invalid_runs"
		record["denominator"] = terminalBenchDenominatorRecord(run, invalidClass, false)
		record["coverage"] = terminalBenchCoverageRecord(matrix, subset, metadata, run, invalidClass, false)
	} else {
		record["scope"].(map[string]any)["denominator_rule"] = "count_valid_tasks"
		record["denominator"] = terminalBenchDenominatorRecord(run, "", true)
		record["coverage"] = terminalBenchCoverageRecord(matrix, subset, metadata, run, "", true)
	}

	if path, hash := terminalBenchArtifactHash(matrixRoot, run.OutputDir, "logs", "agent", "session.log.jsonl"); path != "" {
		record["provenance"].(map[string]any)["session_log_path"] = path
		record["provenance"].(map[string]any)["session_log_sha256"] = hash
	}
	if path, hash := terminalBenchArtifactHash(matrixRoot, run.OutputDir, "logs", "agent", "trajectory.json"); path != "" {
		record["provenance"].(map[string]any)["trajectory_path"] = path
		record["provenance"].(map[string]any)["trajectory_sha256"] = hash
	}
	if path, hash := terminalBenchArtifactHash(matrixRoot, run.OutputDir, "logs", "verifier", "reward.txt"); path != "" {
		record["components"].(map[string]any)["reward_file_path"] = path
		record["components"].(map[string]any)["reward_file_sha256"] = hash
	}

	if run.Reward == nil {
		if reward, err := terminalBenchRewardFromFile(matrixRoot, run.OutputDir); err == nil {
			record["score"] = terminalBenchScoreRecord(run, reward)
		}
	}
	if run.Reward != nil {
		record["score"] = terminalBenchScoreRecord(run, *run.Reward)
	}

	if err := terminalBenchApplyMetadata(record, metadata, prof, run); err != nil {
		return nil, err
	}

	recordID, err := evidence.StableRecordID(record)
	if err != nil {
		return nil, err
	}
	record["record_id"] = recordID
	return record, nil
}

func buildTerminalBenchAggregateRecord(matrixRoot string, matrix *matrixOutput, subset *termbenchSubset, metadata map[string]any, cell matrixCell) (map[string]any, error) {
	record := map[string]any{
		"schema_version": evidence.SchemaVersion,
		"captured_at":    stringOrDefault(metadataPathString(metadata, "captured_at"), time.Now().UTC().Format(time.RFC3339)),
		"source":         terminalBenchSourceRecord(matrixRoot, "matrix.json", "matrix.json"),
		"benchmark":      terminalBenchBenchmarkRecord(matrix, subset, metadata),
		"subject": map[string]any{
			"harness":   cell.Harness,
			"provider":  metadataPathString(metadata, "subject.provider"),
			"model_raw": metadataPathString(metadata, "subject.model_raw"),
		},
		"scope": map[string]any{
			"run_id":           cell.Harness + "/" + cell.ProfileID,
			"subset":           matrixSubsetID(matrix, metadata, subset),
			"subset_id":        matrixSubsetID(matrix, metadata, subset),
			"subset_version":   matrixSubsetVersion(metadata, subset),
			"denominator_rule": "count_valid_tasks",
			"split":            metadataPathString(metadata, "scope.split"),
			"n_tasks":          len(subset.Tasks),
			"task_id":          "",
			"rep":              0,
		},
		"score": map[string]any{
			"metric":    "pass_rate",
			"value":     cellScoreValue(cell),
			"raw_value": cellScoreValue(cell),
			"n":         cell.NRuns,
			"passed":    cell.NValid,
			"failed":    cell.NInvalid,
		},
		"coverage": map[string]any{
			"formula_version":     stringOrDefault(metadataPathString(metadata, "coverage.formula_version"), "fhi/v1"),
			"evidence_window":     stringOrDefault(metadataPathString(metadata, "coverage.evidence_window"), "2026-Q2"),
			"included_benchmarks": []string{"terminal-bench"},
			"included_subsets":    []string{matrixSubsetID(matrix, metadata, subset)},
			"denominator_rule":    "count_valid_tasks",
			"coverage_note":       "aggregate matrix cell imported without task-level rows",
			"confidence_note":     "aggregate record imported from matrix.json cells",
		},
		"denominator": map[string]any{
			"included":         true,
			"policy":           "count_valid_runs_only",
			"reason":           "aggregate cell imported from matrix summary",
			"included_count":   cell.NValid,
			"excluded_count":   cell.NInvalid,
			"excluded_classes": terminalBenchAggregateExcludedClasses(cell),
		},
		"components": map[string]any{
			"matrix_cell_harness":  cell.Harness,
			"matrix_cell_profile":  cell.ProfileID,
			"matrix_cell_cost_usd": cell.CostUSD,
		},
	}
	recordID, err := evidence.StableRecordID(record)
	if err != nil {
		return nil, err
	}
	record["record_id"] = recordID
	return record, nil
}

package main

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestTerminalBenchMatrixImport(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	fixtureDir := filepath.Join(repoRoot, "cmd", "bench", "testdata", "terminalbench-matrix")
	outPath := filepath.Join(t.TempDir(), "terminalbench-evidence.jsonl")

	if code, out := runBenchCLI(t, repoRoot, "evidence", "import-terminalbench", "--work-dir", repoRoot, "--matrix", fixtureDir, "--out", outPath); code != 0 {
		t.Fatalf("import-terminalbench exit=%d output=%s", code, out)
	}

	raw, err := os.ReadFile(outPath)
	if err != nil {
		t.Fatalf("read output: %v", err)
	}
	lines := bytes.Split(bytes.TrimSpace(raw), []byte("\n"))
	if got, want := len(lines), 5; got != want {
		t.Fatalf("record count = %d, want %d\n%s", got, want, string(raw))
	}

	schema := compileBenchmarkEvidenceSchema(t)
	seenIDs := map[string]bool{}
	records := map[string]map[string]any{}
	for _, line := range lines {
		doc := decodeJSONMap(t, line)
		if err := schema.Validate(doc); err != nil {
			t.Fatalf("schema validation failed: %v\n%s", err, string(line))
		}
		recordID := mustStringField(t, doc, "record_id")
		if seenIDs[recordID] {
			t.Fatalf("duplicate record_id %s", recordID)
		}
		seenIDs[recordID] = true

		status := mustStringField(t, doc, "final_status")
		records[status] = doc
	}

	valid := records["graded_pass"]
	if valid == nil {
		t.Fatal("missing graded_pass record")
	}
	assertString(t, valid, "benchmark.name", "terminal-bench")
	assertString(t, valid, "benchmark.version", "2026.05.06")
	assertString(t, valid, "benchmark.dataset", "terminal-bench@2.0")
	assertString(t, valid, "benchmark.subset_id", "tb2-canary")
	assertString(t, valid, "subject.harness", "fiz")
	assertString(t, valid, "subject.provider", "omlx")
	assertString(t, valid, "provenance.fizeau_git_commit", "fa48595c7262b1522ab41897c3f60e128014f598")
	assertString(t, valid, "provenance.harness_wrapper_name", "fiz-native")
	assertString(t, valid, "provenance.provider_version", "0.8.10")
	assertString(t, valid, "provenance.session_log_path", "cells/fiz/vidar-qwen/rep-001/fix-git/logs/agent/session.log.jsonl")
	assertString(t, valid, "provenance.trajectory_path", "cells/fiz/vidar-qwen/rep-001/fix-git/logs/agent/trajectory.json")
	assertString(t, valid, "runtime.deployment_class", "local")
	assertString(t, valid, "runtime.local_runtime_name", "omlx")
	assertString(t, valid, "runtime.local_runtime_version", "0.8.10")
	assertBool(t, valid, "denominator.included", true)
	assertString(t, valid, "scope.denominator_rule", "count_valid_tasks")
	assertString(t, valid, "source.artifact_path", "matrix.json")

	invalidQuota := records["invalid_quota"]
	if invalidQuota == nil {
		t.Fatal("missing invalid_quota record")
	}
	assertString(t, invalidQuota, "subject.harness", "claude")
	assertString(t, invalidQuota, "provenance.harness_wrapper_name", "claude-code")
	assertBool(t, invalidQuota, "denominator.included", false)
	assertString(t, invalidQuota, "denominator.policy", "exclude_invalid_runs")
	assertContainsString(t, invalidQuota, "denominator.excluded_classes", "invalid_quota")
	assertString(t, invalidQuota, "scope.denominator_rule", "exclude_invalid_runs")
	assertString(t, invalidQuota, "final_status", "invalid_quota")
	assertString(t, invalidQuota, "invalid_class", "invalid_quota")
	assertHex64(t, invalidQuota, "provenance.session_log_sha256")
	assertHex64(t, invalidQuota, "provenance.trajectory_sha256")

	invalidProvider := records["invalid_provider"]
	if invalidProvider == nil {
		t.Fatal("missing invalid_provider record")
	}
	assertString(t, invalidProvider, "subject.harness", "opencode")
	assertString(t, invalidProvider, "invalid_class", "invalid_provider")
	assertContainsString(t, invalidProvider, "denominator.excluded_classes", "invalid_provider")
}

func assertContainsString(t *testing.T, doc map[string]any, path, want string) {
	t.Helper()

	got, ok := lookupPath(doc, path)
	if !ok {
		t.Fatalf("missing %s", path)
	}
	values, ok := got.([]any)
	if !ok {
		t.Fatalf("%s = %T, want []any", path, got)
	}
	for _, v := range values {
		if s, ok := v.(string); ok && s == want {
			return
		}
	}
	t.Fatalf("%s missing %q in %#v", path, want, values)
}

func assertHex64(t *testing.T, doc map[string]any, path string) {
	t.Helper()

	got, ok := lookupPath(doc, path)
	if !ok {
		t.Fatalf("missing %s", path)
	}
	str, ok := got.(string)
	if !ok {
		t.Fatalf("%s = %T, want string", path, got)
	}
	if len(str) != 64 {
		t.Fatalf("%s length = %d, want 64", path, len(str))
	}
}

package evidence

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/santhosh-tekuri/jsonschema/v5"
)

const (
	SchemaRelativePath = "scripts/benchmark/benchmark-evidence.schema.json"
	SchemaVersion      = "benchmark-evidence/v1"
)

// Validator loads and applies the benchmark evidence schema from a repo root.
type Validator struct {
	schema *jsonschema.Schema
}

// AppendReport summarizes the effect of an append operation.
type AppendReport struct {
	LedgerPath string
	Added      int
	Duplicates []string
}

// DuplicateRecordsError reports duplicate evidence records that were skipped.
type DuplicateRecordsError struct {
	RecordIDs []string
}

func (e *DuplicateRecordsError) Error() string {
	if e == nil || len(e.RecordIDs) == 0 {
		return "duplicate evidence records"
	}
	return fmt.Sprintf("duplicate evidence records: %s", strings.Join(e.RecordIDs, ", "))
}

// NewValidator compiles the benchmark evidence schema from repoRoot.
func NewValidator(repoRoot string) (*Validator, error) {
	schemaPath := filepath.Join(repoRoot, SchemaRelativePath)
	rawSchema, err := os.ReadFile(schemaPath)
	if err != nil {
		return nil, fmt.Errorf("read evidence schema %s: %w", schemaPath, err)
	}

	compiler := jsonschema.NewCompiler()
	compiler.AssertFormat = true
	if err := compiler.AddResource("benchmark-evidence.schema.json", bytes.NewReader(rawSchema)); err != nil {
		return nil, fmt.Errorf("add evidence schema: %w", err)
	}
	schema, err := compiler.Compile("benchmark-evidence.schema.json")
	if err != nil {
		return nil, fmt.Errorf("compile evidence schema: %w", err)
	}
	return &Validator{schema: schema}, nil
}

// ValidateFile validates one JSON or JSONL evidence file and returns the
// normalized records, including any generated record_id values.
func (v *Validator) ValidateFile(path string) ([]map[string]any, error) {
	rawRecords, err := loadRecords(path)
	if err != nil {
		return nil, err
	}

	normalized := make([]map[string]any, 0, len(rawRecords))
	for i, record := range rawRecords {
		doc, _, err := v.normalizeRecord(record)
		if err != nil {
			return nil, fmt.Errorf("%s line %d: %w", path, i+1, err)
		}
		normalized = append(normalized, doc)
	}
	return normalized, nil
}

// AppendLedger appends validated evidence records to a JSONL ledger.
func (v *Validator) AppendLedger(inputPath, ledgerPath string) (*AppendReport, error) {
	incoming, err := v.ValidateFile(inputPath)
	if err != nil {
		return nil, err
	}

	existing, err := loadLedgerRecords(ledgerPath)
	if err != nil {
		return nil, err
	}

	existingByFingerprint := make(map[string]string, len(existing))
	existingByID := make(map[string]string, len(existing))
	for _, record := range existing {
		fp, err := fingerprintRecord(record)
		if err != nil {
			return nil, err
		}
		id, _ := record["record_id"].(string)
		existingByFingerprint[fp] = id
		existingByID[id] = fp
	}

	var (
		additions  []map[string]any
		duplicates []string
	)
	seenNew := make(map[string]struct{}, len(incoming))
	for _, record := range incoming {
		fp, err := fingerprintRecord(record)
		if err != nil {
			return nil, err
		}
		id, _ := record["record_id"].(string)

		if existingID, ok := existingByFingerprint[fp]; ok {
			duplicates = append(duplicates, chooseDuplicateID(id, existingID))
			continue
		}
		if existingFP, ok := existingByID[id]; ok && existingFP != fp {
			return nil, fmt.Errorf("record_id %q already exists with different content", id)
		}
		if _, ok := seenNew[fp]; ok {
			duplicates = append(duplicates, id)
			continue
		}

		seenNew[fp] = struct{}{}
		additions = append(additions, record)
		existingByFingerprint[fp] = id
		existingByID[id] = fp
	}

	if len(additions) > 0 {
		if err := appendRecords(ledgerPath, additions); err != nil {
			return nil, err
		}
	}

	report := &AppendReport{
		LedgerPath: ledgerPath,
		Added:      len(additions),
		Duplicates: append([]string(nil), duplicates...),
	}
	if len(duplicates) > 0 {
		return report, &DuplicateRecordsError{RecordIDs: duplicates}
	}
	return report, nil
}

// StableRecordID returns the deterministic content-derived record_id for a
// record that omits record_id.
func StableRecordID(doc map[string]any) (string, error) {
	normalized, err := cloneDocument(doc)
	if err != nil {
		return "", err
	}
	delete(normalized, "record_id")
	sum := sha256.Sum256(mustMarshal(normalized))
	return hex.EncodeToString(sum[:]), nil
}

func (v *Validator) normalizeRecord(doc map[string]any) (map[string]any, string, error) {
	normalized, err := cloneDocument(doc)
	if err != nil {
		return nil, "", err
	}
	fp, err := fingerprintRecord(normalized)
	if err != nil {
		return nil, "", err
	}
	if id, _ := normalized["record_id"].(string); strings.TrimSpace(id) == "" {
		normalized["record_id"] = fp
	}
	if err := v.schema.Validate(normalized); err != nil {
		return nil, "", fmt.Errorf("schema validation failed: %w", err)
	}
	return normalized, fp, nil
}

func fingerprintRecord(doc map[string]any) (string, error) {
	normalized, err := cloneDocument(doc)
	if err != nil {
		return "", err
	}
	delete(normalized, "record_id")
	sum := sha256.Sum256(mustMarshal(normalized))
	return hex.EncodeToString(sum[:]), nil
}

func loadLedgerRecords(path string) ([]map[string]any, error) {
	info, err := os.Stat(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("stat ledger %s: %w", path, err)
	}
	if info.Size() == 0 {
		return nil, nil
	}
	return loadRecords(path)
}

func loadRecords(path string) ([]map[string]any, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read evidence file %s: %w", path, err)
	}

	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 {
		return nil, fmt.Errorf("evidence file %s is empty", path)
	}

	if record, err := decodeObject(trimmed); err == nil {
		return []map[string]any{record}, nil
	}

	lines := bytes.Split(trimmed, []byte("\n"))
	records := make([]map[string]any, 0, len(lines))
	for i, line := range lines {
		line = bytes.TrimSpace(line)
		if len(line) == 0 {
			continue
		}
		record, err := decodeObject(line)
		if err != nil {
			return nil, fmt.Errorf("%s line %d: %w", path, i+1, err)
		}
		records = append(records, record)
	}
	if len(records) == 0 {
		return nil, fmt.Errorf("evidence file %s contains no records", path)
	}
	return records, nil
}

func decodeObject(raw []byte) (map[string]any, error) {
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil, err
	}
	return doc, nil
}

func cloneDocument(doc map[string]any) (map[string]any, error) {
	raw, err := json.Marshal(doc)
	if err != nil {
		return nil, fmt.Errorf("marshal evidence record: %w", err)
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, fmt.Errorf("clone evidence record: %w", err)
	}

}

func terminalBenchBaseRecord(matrixRoot string, matrix *matrixOutput, subset *termbenchSubset, metadata map[string]any, run matrixRunReport, prof *profile.Profile) map[string]any {
