		"--profiles", "noop",
		"--reps", "1",
		"--out", outDir,
	}); code != 0 {
		t.Fatalf("cmdMatrix exit = %d, want 0", code)
	}
	if code := cmdMatrixAggregate([]string{outDir}); code != 0 {
		t.Fatalf("cmdMatrixAggregate exit = %d, want 0", code)
	}
	for _, name := range []string{"matrix.json", "matrix.md", "costs.json"} {
		if info, err := os.Stat(filepath.Join(outDir, name)); err != nil {
			t.Fatalf("%s missing: %v", name, err)
		} else if info.Size() == 0 {
			t.Fatalf("%s is empty", name)
		}
	}
}

func writeFixtureRun(t *testing.T, outDir string, run matrixRunReport) {
	t.Helper()
	dir := matrixTupleDir(outDir, run.Harness, run.ProfileID, run.Rep, run.TaskID)
	run.OutputDir = dir
	if err := writeJSONAtomic(filepath.Join(dir, matrixReportName), run); err != nil {
		t.Fatal(err)
	}
}

func intPtr(v int) *int {
	return &v
}

package main

import (
	"regexp"
	"strings"
)

const (
	matrixInvalidQuota    = "invalid_quota"
	matrixInvalidAuth     = "invalid_auth"
	matrixInvalidSetup    = "invalid_setup"
	matrixInvalidProvider = "invalid_provider"
)

var (
	matrixInvalidQuotaPattern    = regexp.MustCompile(`(?i)(api_error_status:\s*429|out_of_credits|credits?\s+exhausted|usage\s+exhausted|rate\s*limit|too many requests|quota\s+exhausted|quota\s+exceeded)`)
	matrixInvalidAuthPattern     = regexp.MustCompile(`(?i)(unauthori[sz]ed|authentication failed|invalid api key|missing credentials?|not signed in|login required|account .*not .*authenticated|oauth.*failed|credential.*missing|account .*required|access denied)`)
	matrixInvalidSetupPattern    = regexp.MustCompile(`(?i)(binary not found|no such file or directory|exec format error|cannot execute binary file|wrong architecture|architecture mismatch|task dir not found|submodule not initialized|failed to start|wrapper startup|startup failed|docker.*(failed|error)|container.*(failed|error)|image.*(failed|error|not found)|operation not permitted|permission denied|sandbox.*failed|setup failed|preflight failure)`)
	matrixInvalidProviderPattern = regexp.MustCompile(`(?i)(connection refused|connection reset|socket hang up|fetch failed|tls handshake|dns|eof|timed out|timeout|stream closed|broken pipe|remote closed|upstream|service unavailable|bad gateway|gateway timeout|failed to connect|provider transport|network error)`)
)

func classifyMatrixInvalid(report matrixRunReport) string {
	switch report.FinalStatus {
	case "graded_pass", "graded_fail", "verifier_fail":
		return ""
	}
	if isMatrixKnownInvalidClass(report.FinalStatus) {
		return report.FinalStatus
	}
	if report.InvalidClass != "" {
		return report.InvalidClass
	}
	if matrixHasMeaningfulAttempt(report) {
		return ""
	}
	blob := matrixInvalidSignalBlob(report)
	switch {
	case matrixInvalidQuotaPattern.MatchString(blob):
		return matrixInvalidQuota
	case matrixInvalidAuthPattern.MatchString(blob):
		return matrixInvalidAuth
	case matrixInvalidSetupPattern.MatchString(blob):
		return matrixInvalidSetup
	case matrixInvalidProviderPattern.MatchString(blob):
		return matrixInvalidProvider
	default:
		return ""
	}
}

func isMatrixKnownInvalidClass(status string) bool {
	switch status {
	case matrixInvalidQuota, matrixInvalidAuth, matrixInvalidSetup, matrixInvalidProvider:
		return true
	default:
		return false
	}
}

func matrixHasMeaningfulAttempt(report matrixRunReport) bool {
	return intValue(report.Turns) > 0 ||
		intValue(report.ToolCalls) > 0 ||
		intValue(report.ToolCallErrors) > 0 ||
		intValue(report.InputTokens) > 0 ||
		intValue(report.OutputTokens) > 0 ||
		intValue(report.CachedInputTokens) > 0 ||
		intValue(report.RetriedInputTokens) > 0
}

func matrixInvalidSignalBlob(report matrixRunReport) string {
	parts := []string{
		report.Error,
		report.ProcessOutcome,
		report.FinalStatus,
		strings.Join(report.AdapterTranslationNotes, " "),
		strings.Join(report.Command, " "),
	}
	var out []string
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return strings.ToLower(strings.Join(out, "\n"))
}

package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/benchmark/evidence"
)

func cmdEvidence(args []string) int {
	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "Usage: %s evidence <subcommand>\n\nSubcommands:\n  validate            Validate evidence records in a JSON/JSONL file\n  append              Append validated evidence records to a JSONL ledger\n  import-terminalbench Import a TerminalBench matrix directory into JSONL evidence\n  import-beadbench     Import a beadbench report.json into JSONL evidence\n  import-external      Import curated external benchmark snapshots into JSONL evidence\n", benchCommandName())
		return 2
	}

	switch args[0] {
	case "validate":
		return cmdEvidenceValidate(args[1:])
	case "append":
		return cmdEvidenceAppend(args[1:])
	case "import-terminalbench":
		return cmdEvidenceImportTerminalBench(args[1:])
	case "import-beadbench":
		return cmdEvidenceImportBeadBench(args[1:])
	case "import-external":
		return cmdEvidenceImportExternal(args[1:])
	case "help", "-h", "--help":
		fmt.Fprintf(os.Stderr, "Usage: %s evidence validate <file>\n       %s evidence append --in <records.jsonl> --ledger <ledger.jsonl>\n       %s evidence import-terminalbench --matrix <dir> --out <records.jsonl>\n       %s evidence import-beadbench --report <report.json> --out <records.jsonl>\n       %s evidence import-external --source <fixture> --out <records.jsonl>\n", benchCommandName(), benchCommandName(), benchCommandName(), benchCommandName(), benchCommandName())
		return 0
	default:
		fmt.Fprintf(os.Stderr, "%s evidence: unknown subcommand %q\n", benchCommandName(), args[0])
		return 2
	}
}

func cmdEvidenceValidate(args []string) int {
	fs := flagSet("evidence validate")
	workDir := fs.String("work-dir", "", "Repository root (default: cwd)")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if fs.NArg() != 1 {
		fmt.Fprintf(os.Stderr, "Usage: %s evidence validate <file>\n", benchCommandName())
		return 2
	}

	validator, err := evidence.NewValidator(resolveWorkDir(*workDir))
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s evidence validate: %v\n", benchCommandName(), err)
		return 1
	}
	if _, err := validator.ValidateFile(fs.Arg(0)); err != nil {
		fmt.Fprintf(os.Stderr, "%s evidence validate: %v\n", benchCommandName(), err)
		return 1
	}
	return 0
}

func cmdEvidenceAppend(args []string) int {
	fs := flagSet("evidence append")
	workDir := fs.String("work-dir", "", "Repository root (default: cwd)")
	input := fs.String("in", "", "Evidence records JSON/JSONL file")
	ledger := fs.String("ledger", "", "Append-only ledger JSONL path")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if *input == "" || *ledger == "" {
		fmt.Fprintf(os.Stderr, "Usage: %s evidence append --in <records.jsonl> --ledger <ledger.jsonl>\n", benchCommandName())
		return 2
	}

	validator, err := evidence.NewValidator(resolveWorkDir(*workDir))
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s evidence append: %v\n", benchCommandName(), err)
		return 1
	}
	report, err := validator.AppendLedger(*input, *ledger)
	if report != nil && report.Added > 0 {
		fmt.Fprintf(os.Stderr, "%s evidence append: appended %d record(s) to %s\n", benchCommandName(), report.Added, report.LedgerPath)
	}
	if err != nil {
		if dupErr, ok := err.(*evidence.DuplicateRecordsError); ok {
			fmt.Fprintf(os.Stderr, "%s evidence append: %s\n", benchCommandName(), dupErr.Error())
			return 1
		}
		fmt.Fprintf(os.Stderr, "%s evidence append: %v\n", benchCommandName(), err)
		return 1
	}
	if report != nil && len(report.Duplicates) > 0 {
		fmt.Fprintf(os.Stderr, "%s evidence append: duplicate records: %s\n", benchCommandName(), strings.Join(report.Duplicates, ", "))
		return 1
	}
	return 0
}
